import{_ as e,c as t,o as r,ag as o}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/settings.md","filePath":"zh-CN/guide/settings.md","lastUpdated":1791311600000}'),i={name:"zh-CN/guide/settings.md"};function l(n,a,s,d,h,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h1><p>nPlyr 的设置窗口按标签页组织。本页带你了解大多数人最先更改的若干项。</p><h2 id="外观与语言" tabindex="-1">外观与语言 <a class="header-anchor" href="#外观与语言" aria-label="Permalink to &quot;外观与语言&quot;">​</a></h2><h3 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h3><p>nPlyr 内置多个主题，每个都以一个标志性的强调色为基调。切换主题时，整个界面——包括每一个打开的窗口——都会立即更新。你也可以自动<strong>跟随系统外观</strong>（浅色 / 深色）。</p><h3 id="语言" tabindex="-1">语言 <a class="header-anchor" href="#语言" aria-label="Permalink to &quot;语言&quot;">​</a></h3><p>界面已本地化为 <strong>25 种语言</strong>。更改语言会在所有已打开窗口与菜单栏上立即生效——无需重启。（这一实时切换是通过在语言变化时重建每个窗口的视图来实现的。）</p><h2 id="通用" tabindex="-1">通用 <a class="header-anchor" href="#通用" aria-label="Permalink to &quot;通用&quot;">​</a></h2><ul><li><strong>浏览器 user-agent</strong>——选择 <em>自动</em>、<em>移动端</em>、<em>桌面端（PC）</em>，或粘贴一个<strong>自定义</strong> UA。该 UA 由<a href="/zh-CN/guide/browser.html">嗅探器</a>以及播放/解析在需要时采用。规则也可以指定自己的 UA；只有当选择跟随规则的值时，齿轮设置才会覆盖它。</li><li><strong>文件关联</strong>——让 nPlyr 在你在 Finder 中双击本地音视频文件（<code>.mp4</code>、<code>.mkv</code>、<code>.mov</code>、<code>.m4v</code>、<code>.webm</code>、<code>.flv</code>、<code>.mka</code> 等）时打开它们。</li></ul><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><ul><li>已下载媒体的默认保存位置。</li><li>是否提供<strong>边下边播</strong>。</li><li>清晰度默认值，以及是否自动下载字幕。</li></ul><h2 id="播放器" tabindex="-1">播放器 <a class="header-anchor" href="#播放器" aria-label="Permalink to &quot;播放器&quot;">​</a></h2><ul><li>默认播放速度。</li><li>手势偏好（触控板 / 触摸灵敏度）。</li><li>画中画与 AirPlay 默认值。</li></ul><h2 id="去广告" tabindex="-1">去广告 <a class="header-anchor" href="#去广告" aria-label="Permalink to &quot;去广告&quot;">​</a></h2><p>订阅 Chrome 兼容的过滤列表。nPlyr 会在浏览器中以及播放期间过滤请求。去广告与边下边播互斥。</p><h2 id="小程序" tabindex="-1">小程序 <a class="header-anchor" href="#小程序" aria-label="Permalink to &quot;小程序&quot;">​</a></h2><p>管理已导入的小程序与规则源：添加、编辑、重排与删除。<strong>免费层级</strong>会限制小程序的数量；解锁后移除该限制，以一次性购买形式存储。参见<a href="/zh-CN/guide/miniapps.html">小程序</a>。</p>',17)])])}const g=e(i,[["render",l]]);export{m as __pageData,g as default};
